public class JsoupHelper {

    @Test
    public void testConnectMethod() throws MalformedURLException, UnknownHostException {
        URL url = new URL("https://example.com");
        HttpConnection connection = JsoupHelper.connect(url);
        assertEquals(connection, JsoupHelper.connect("https://example.com"));
    }

    @Test
    public void testConnectMethodWithProxy() throws MalformedURLException, UnknownHostException {
        URL url = new URL("https://proxy.example.com");
        HttpConnection connection = JsoupHelper.connect(url);
        assertEquals(connection, JsoupHelper.connect(new org.jsoup.parser.Parser(), "https://proxy.example.com"));
    }

    @Test
    public void testConnectMethodWithUserAgent() throws MalformedURLException, UnknownHostException {
        URL url = new URL("https://example.com");
        String userAgent = "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/58.0.3029.110 Safari/537.3";
        HttpConnection connection = JsoupHelper.connect(url, userAgent);
        assertEquals(connection, JsoupHelper.connect("https://example.com", "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/58.0.3029.110 Safari/537.3"));
    }

    @Test
    public void testTimeout() throws IOException {
        HttpConnection connection = JsoupHelper.connect("https://example.com", 100);
        assertEquals(connection.timeout(100), true);
    }

    @Test
    public void testMaxBodySize() throws IOException {
        HttpConnection connection = JsoupHelper.connect("https://example.com", 1024, "application/octet-stream");
        assertEquals(connection.maxBodySize(1024), 1024);
    }

    @Test
    public void testFollowRedirects() throws MalformedURLException, UnknownHostException {
        HttpConnection connection = JsoupHelper.connect("https://example.com");
        assertEquals(connection.followRedirects(true), true);
    }

    @Test
    public void testReferrer() throws MalformedURLException, UnknownHostException {
        HttpConnection connection = JsoupHelper.connect("https://example.com", " referrals-to-redirect.html#some-string");
        assertEquals(connection.referrer("referrals-to-redirect.html#some-string"), "referrals-to-redirect.html#some-string");
    }

    @Test
    public void testIgnoreHttpErrors() throws MalformedURLException, UnknownHostException {
        HttpConnection connection = JsoupHelper.connect("https://example.com");
        assertEquals(connection.ignoreHttpErrors(true), true);
    }

    @Test
    public void testIgnoreContentType() throws MalformedURLException, UnknownHostException {
        HttpConnection connection = JsoupHelper.connect("https://example.com");
        assertEquals(connection.ignoreContentType(false), false);
    }

    @Test
    public void testDataKeyVals() throws IOException {
        HttpConnection connection = JsoupHelper.connect("https://example.com", "key1=value1&key2=value2");
        assertEquals(connection.data("key1", "value1"), null);
    }

    @Test
    public void testHeaderNameValues() throws IOException {
        HttpConnection connection = JsoupHelper.connect("https://example.com", "key1=value1&key2=value2");
        assertEquals(connection.header("key1", "value1"), null);
    }

    @Test
    public void testCookieNameValues() throws IOException {
        HttpConnection connection = JsoupHelper.connect("https://example.com", "key1=value1&key2=value2");
        assertEquals(connection.cookie("key1", "value1"), null);
    }

    @Test
    public void testCookies() throws IOException {
        HttpConnection connection = JsoupHelper.connect("https://example.com", "key1=value1&key2=value2");
        assertEquals(connection.cookies(Collections.singletonMap("key1", "value1")), Collections.emptyMap());
    }
